const { excelConverterApi } = window;
const treeGridWorksheet = excelConverterApi.convertTreeGrid(window.mainPage._grid._grid);
const worksheets = [{
  ...treeGridWorksheet,
  title: 'Innovator'
}];

const fileName = aras.getResource('', 'aras_object.export2excel_file_prefix');
const fileBlob = await excelConverterApi.convertJsonToExcel(worksheets);
window.ArasModules.vault.saveBlob(fileBlob, `${fileName}.xlsx`);
